/* analyst literature DB: AI claims from the top-tier panel, with verified sources and verbatim quotes */
window.ANALYSTS=[{"id": "a1", "author": "Adam Tooze", "date": "2020-06-14", "src_title": "The history of AI is… – ADAM TOOZE", "url": "https://adamtooze.com/2020/06/14/the-history-of-ai-is/", "quote": "The history of AI is of periodic bouts of overexcitement interspersed with 'ai winters', in which limits become apparent", "claim": "Tooze frames AI's history as cyclical hype-bust, with each wave of enthusiasm followed by a reckoning with limits.", "scope": "capability", "pe_sub": "", "stance": "shares-concern", "note": "Directly echoes Zitron's fraud/hype thesis; Tooze supplies the historical pattern Zitron treats as the current moment."}, {"id": "a2", "author": "Adam Tooze", "date": "2023-06-02", "src_title": "Ones & Tooze: Tech's New Trillionaire – ADAM TOOZE", "url": "https://adamtooze.com/2023/06/02/ones-tooze-techs-new-trillionaire/", "quote": "", "claim": "Tooze and Abadi examine whether Nvidia's doubling in value on AI chip demand is justified or overvalued, framing the question as genuinely open.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Raises the same valuation-vs-reality question Zitron pounds; URL verified live but episode is audio-only, no transcript available to yield verbatim quote."}, {"id": "a3", "author": "Adam Tooze", "date": "2023-06-05", "src_title": "Adam Tooze on Why the Value of AI Chip Company Nvidia Is Soaring", "url": "https://foreignpolicy.com/2023/06/05/adam-tooze-ai-chip-company-nvidia-soaring/", "quote": "", "claim": "Tooze examines Nvidia's soaring valuation in relation to the AI boom, treating the scale of the price move as requiring explanation rather than celebration.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Tooze treats Nvidia's trillion-dollar run as a live analytical puzzle, consistent with bubble skepticism Zitron shares, though Tooze does not call it fraud. Paywalled; URL verified 200."}, {"id": "a4", "author": "Adam Tooze", "date": "2024-08-17", "src_title": "Brazil's soy domination. The AI investment boom. Hegel on revolution & nuclear arms racing.", "url": "https://adamtooze.substack.com/p/brazils-soy-domination-the-ai-investment", "quote": "Big Tech spending on AI reached a combined $106bn in the first six months of 2024.", "claim": "By mid-2024 the Big Tech AI capex wave had already reached $106bn in a single half-year, with analysts projecting at least $80bn more in 2025.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Tooze documents the capex scale without pronouncing it justified; the implicit question of whether revenues will follow is exactly Zitron's concern. Quote sourced from FT via Tooze curation."}, {"id": "a5", "author": "Adam Tooze", "date": "2025-07-29", "src_title": "How AI is eating the internet. Where to buy an affordable American-badged car…", "url": "https://adamtooze.substack.com/p/how-ai-is-eating-the-internet-where", "quote": "AI is undoing the search-bargain on which the internet has hitherto depended", "claim": "AI-generated search overviews are destroying the traffic-for-content deal between Google and publishers, with global search traffic down ~15% in a year.", "scope": "diffusion-utility", "pe_sub": "", "stance": "shares-concern", "note": "Tooze frames AI deployment as actively destructive to the existing internet economy, closer to Zitron's harm narrative than a pro-AI booster position."}, {"id": "a6", "author": "Adam Tooze", "date": "2025-09-19", "src_title": "Is Artificial Intelligence Worth the Investment?", "url": "https://foreignpolicy.com/2025/09/19/is-artificial-intelligence-worth-the-investment/", "quote": "", "claim": "Tooze uses the economist's frame of AI as a 'general purpose technology', a category whose impacts are subtle and hard to detect immediately, to ask whether $400bn in annual AI infrastructure spend can possibly pay off.", "scope": "diffusion-utility", "pe_sub": "", "stance": "orthogonal", "note": "Tooze applies GPT theory (Bresnahan/Trajtenberg lineage) to hold open the possibility of delayed but real productivity gains, a dimension Zitron ignores in favor of a simpler fraud verdict. Paywalled; URL verified 200."}, {"id": "a7", "author": "Adam Tooze", "date": "2025-09-19", "src_title": "What AI Means for the Economy and for Politics | Ones and Tooze Ep. 209", "url": "https://foreignpolicy.com/podcasts/ones-and-tooze/what-ai-means-for-the-economy-and-for-politics/", "quote": "", "claim": "In the first of an AI series, Tooze and Abadi discuss how 'general purpose technology' is a phrase economists developed to describe how technologies can have subtle and hard-to-detect immediate impacts on the economy.", "scope": "diffusion-utility", "pe_sub": "", "stance": "orthogonal", "note": "GPT framing keeps open a long-run productivity case that Zitron never engages; Tooze neither endorses nor dismisses the AI boom, he contextualizes it historically."}, {"id": "a8", "author": "Adam Tooze", "date": "2026-01-08", "src_title": "Top Links 976 AI investment surges. China in Saudi Arabia…", "url": "https://adamtooze.substack.com/p/top-links-976-ai-investment-surges", "quote": "Tech investment has become a truly major driver of the US economy: approaching 5 percent of GDP.", "claim": "AI/tech capex has grown so large it now functions as a macroeconomic demand driver approaching 5% of US GDP.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Tooze identifies a Keynesian-stimulus dimension of AI capex, real economic activity regardless of whether the technology delivers, that Zitron's pure-fraud frame misses."}, {"id": "a9", "author": "Adam Tooze", "date": "2026-02-12", "src_title": "Top Links 1011 Does AI raise productivity?", "url": "https://adamtooze.substack.com/p/top-links-1011-does-ai-raise-productivity", "quote": "There is a correlation between productivity growth and reported AI-use", "claim": "Tooze flags early empirical evidence of a positive correlation between AI adoption and productivity, while leaving the causal question open.", "scope": "diffusion-utility", "pe_sub": "", "stance": "rejects-conclusion", "note": "Even a hedged acknowledgment of an AI-productivity correlation contradicts Zitron's flat claim that AI produces no real value anywhere."}, {"id": "a10", "author": "Adam Tooze", "date": "2026-02-13", "src_title": "Is This What an Economic Bubble Looks Like?", "url": "https://foreignpolicy.com/2026/02/13/is-this-what-an-economic-bubble-looks-like/", "quote": "", "claim": "Tooze identifies three distinct types of economic bubble that could afflict the AI industry and notes that AI capex at ~$650bn (roughly 2% of GDP) puts the US in the ballpark of previous tech booms.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Tooze takes bubble risk seriously but with more precision than Zitron, he is asking which type of bubble, not simply declaring fraud. Paywalled; URL verified 200."}, {"id": "a11", "author": "Adam Tooze", "date": "2026-02-13", "src_title": "The AI Economy | Ones and Tooze", "url": "https://foreignpolicy.com/podcasts/ones-and-tooze/the-ai-economy/", "quote": "", "claim": "Big tech companies directing at least $650bn in annual capex to AI may be stimulating the US economy in the short term even if the long-term payoff is uncertain.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "The 'AI as de facto fiscal stimulus' reading is orthogonal to Zitron's framework, which evaluates AI purely on product utility rather than aggregate demand effects."}, {"id": "a12", "author": "Adam Tooze", "date": "2026-05-08", "src_title": "America's AI import boom. The pushback on Chinese pea protein…", "url": "https://adamtooze.substack.com/p/americas-ai-import-boom-the-pushback", "quote": "American imports related to the artificial intelligence boom have more than doubled since 2023 while non-AI imports have fallen.", "claim": "The AI investment boom has driven a structural widening of the US trade deficit, AI-related imports doubling even as tariffs hit record highs.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Tooze identifies a macro footprint of AI capex (trade flows, Taiwan/Mexico supply chains) that is orthogonal to Zitron's product-utility critique but confirms the scale is real."}, {"id": "a13", "author": "Adam Tooze", "date": "2026-05-11", "src_title": "Chartbook 447: The US economy in May 2026 – How much cognitive dissonance can you handle?", "url": "https://adamtooze.substack.com/p/chartbook-447-the-us-economy-in-may", "quote": "the entire big tech-AI nexus is self-feeding to an extraordinary degree", "claim": "Tooze argues the AI investment cycle is circular and self-referential: hyperscalers fund AI firms that become their own biggest cloud customers, inflating valuations all around.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "The circular-money critique is structurally identical to Zitron's claim that AI revenues are fake, both see a loop without external grounding."}, {"id": "a14", "author": "Adam Tooze", "date": "2026-05-11", "src_title": "Chartbook 447: The US economy in May 2026 – How much cognitive dissonance can you handle?", "url": "https://adamtooze.substack.com/p/chartbook-447-the-us-economy-in-may", "quote": "AI will make a few rich but the majority will face unprecedented adjustment shocks", "claim": "If AI boosters are right that the technology transforms the economy, the distributional outcome is sharply polarizing: concentrated gains at the top, large adjustment costs for most workers.", "scope": "political-economy", "pe_sub": "distribution", "stance": "orthogonal", "note": "Tooze takes AI's transformative potential seriously enough to worry about its distributional fallout, a register Zitron never enters because he denies the technology works at all."}, {"id": "a15", "author": "Adam Tooze", "date": "2026-05-12", "src_title": "Tooze on the K-Shaped Economy and Its Global Effects", "url": "https://foreignpolicy.com/2026/05/12/tooze-k-shaped-economy-us-ai-cantillon-wealth-distribution/", "quote": "what we're actually experiencing right now is what monetary theorists would call endogenously generated credit, which is being generated off the back of a huge surge of investment and confidence and optimism about a particular sector, which then warrants credit creation", "claim": "Tooze applies a Cantillon/endogenous-money framework to AI: the boom generates its own credit, concentrates wealth at the entry point of the money flow, and intensifies a K-shaped economy.", "scope": "political-economy", "pe_sub": "market-concentration", "stance": "orthogonal", "note": "This is a political-economy critique of AI's financialization that goes well beyond Zitron's consumer-product fraud frame, Tooze is analyzing structural wealth redistribution, not whether ChatGPT is useful."}, {"id": "a16", "author": "Adam Tooze", "date": "2026-06-02", "src_title": "US Stock Market Bubble Concentration. AI-related Stocks. Post-War Iranian Economy & The Paris Commune.", "url": "https://adamtooze.substack.com/p/us-stock-market-bubble-concentration", "quote": "70 percent of the US market's growth has been driven by AI", "claim": "Since ChatGPT's November 2022 release, 70% of total US equity market growth has been attributable to AI-related stocks, reaching concentration levels not seen in a century.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Documents the bubble-concentration thesis quantitatively; consistent with Zitron's claim that AI is a market mania, though Tooze attributes the data to Michael Harnett (BofA) and Jim Bianco."}, {"id": "a17", "author": "Matt Levine", "date": "2023-11-20", "src_title": "Money Stuff: Who Controls OpenAI?", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-who-controls-openai", "quote": "The board has all the governance rights, and the investors have none … But they have the money.", "claim": "Levine identifies the core structural tension at OpenAI: a nonprofit board with legal control but no financial stake vs. investors with billions in but no governance rights, a structure that makes it vulnerable to power struggles, not a straightforward fraud.", "scope": "finance-markets", "pe_sub": "", "stance": "rejects-conclusion", "note": "Verbatim from Yahoo Finance article quoting the Nov 20 2023 Money Stuff column (Yahoo URL returned 429 at time of curl check; quote also sourced via Bloomberg Law page confirmed 200). Levine also quoted: 'The board can keep running OpenAI forever if it wants, as a technical matter of controlling the relevant legal entities. But if everyone quits to join Sam Altman at Microsoft, then what is the point of continuing to control OpenAI?'"}, {"id": "a18", "author": "Matt Levine", "date": "2025-09-29", "src_title": "Money Stuff: The Perfect AI Startup", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-the-perfect-ai-startup", "quote": "If you run a big artificial intelligence lab in 2025, your company has two important sources of value: [1] Presumably you are building some sort of AI thing. Probably that thing (1) loses a lot of money now but (2) has some plausible path to making a gajillion dollars eventually. You are in the business of burning a lot of investor cash to build God, which would be valuable if you succeed. [2] You employ a lot of AI researchers, and their market value is, what, at least $10 million each? Much more, if they're good?", "claim": "Levine characterizes AI labs as having two distinct value components, the product bet and the talent stockpile, and treats both as legitimate financial objects, not symptoms of a Ponzi scheme.", "scope": "finance-markets", "pe_sub": "", "stance": "rejects-conclusion", "note": "Verbatim from pre-paywall intro of bloomberglaw page, date confirmed 2025-09-29. URL 200."}, {"id": "a19", "author": "Matt Levine", "date": "2025-10-06", "src_title": "Money Stuff: OpenAI Is Good at Deals", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-openai-is-good-at-deals", "quote": "This deal between OpenAI and AMD was obviously going to create a lot of stock-market value: The announcement of the deal would predictably increase the market value of AMD … Why not use that value to subsidize the deal? Schematically, OpenAI could buy AMD stock to predictably profit from the stock-price bump it created. Just going out and doing that in the market would be awkward — it might look like insider trading — but buying the stock from AMD is fine.", "claim": "Levine explains the AMD-OpenAI deal as a mechanism where the announcement itself creates AMD market-cap gain (~$78B) and OpenAI structures a stock-swap so both sides capture some of that value, circular in form, but legally routine; distinct from fraud.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Quote verified on Acadian asset management article which cites Bloomberg opinion piece dated Oct 6 2025. The Hacker News thread (item 45522103) carries the same dialogue satire of this mechanism. URL returns 200."}, {"id": "a20", "author": "Matt Levine", "date": "2025-10-06", "src_title": "Money Stuff: OpenAI Is Good at Deals", "url": "https://news.ycombinator.com/item?id=45522103", "quote": "OpenAI: We would like six gigawatts worth of your chips to do inference.\n\nAMD: Terrific. That will be $78 billion. How would you like to pay?\n\nOpenAI: Well, we were thinking that we would announce the deal, and that would add $78 billion to the value of your company, which should cover it.\n\nAMD: …\n\nOpenAI: …\n\nAMD: No I'm pretty sure you have to pay for the chips.\n\nOpenAI: Why?\n\nAMD: I dunno, just seems wrong not to.\n\nOpenAI: Okay. Why don't we pay you cash for the value of the chips, and you give us back stock, and when we announce the deal the stock will go up and we'll get our $78 billion back.\n\nAMD: Yeah I guess that works though I feel like we should get some of the value?\n\nOpenAI: Okay you can have half. You give us stock worth like $35 billion and you keep the rest.", "claim": "Levine illustrates the AMD-OpenAI deal as a hypothetical dialogue: deal announcements by OpenAI create market-cap gains that can be recycled back to fund the purchase, a form of circular value creation, not classical fraud.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Verbatim from Hacker News item 45522103 (gruez's comment reproducing the Levine column dialogue). URL 200 confirmed. Original column: bloomberg.com/opinion/newsletters/2025-10-06/openai-is-good-at-deals (403 to unauthenticated)."}, {"id": "a21", "author": "Matt Levine", "date": "2025-10-13", "src_title": "Money Stuff: OpenAI Keeps Doing Deals", "url": "https://news.bloomberglaw.com/daily-labor-report/matt-levines-money-stuff-openai-keeps-doing-deals", "quote": "The essence of finance is time travel. In the future, your factory will make widgets and you will sell them profitably, so you can borrow money, today, to build the factory to make the widgets to sell to repay the money. If you go to a bank with an architect's plans for the widget factory, and a business plan for making and selling the widgets, and a good track record of profitably manufacturing and selling widgets, the bank will be happy to lend you the money to build the factory.", "claim": "Levine frames AI infrastructure financing as legitimate 'time-travel finance': borrowing today against future AI revenues is structurally normal, not inherently fraudulent; the question is whether the future revenues materialize.", "scope": "finance-markets", "pe_sub": "", "stance": "rejects-conclusion", "note": "Verbatim from the pre-paywall intro of the bloomberglaw page, verified live 200. Levine's frame explicitly separates financial structure from product legitimacy."}, {"id": "a22", "author": "Matt Levine", "date": "2025-10-13", "src_title": "Money Stuff: OpenAI Keeps Doing Deals (via Techmeme)", "url": "https://www.techmeme.com/251014/p6", "quote": "To raise $1 trillion, you need more than a compelling science-fiction vision of your world-changing product. You need a compelling science-fiction vision of world-changing financial engineering.", "claim": "Levine argues Altman's trillion-dollar raise requires not just AI hype but financial engineering hype, treating the deal structures themselves as a spectacle alongside the technology claims.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Verbatim from Techmeme page (techmeme.com/251014/p6), which excerpts the Oct 13 2025 Money Stuff column. URL 200 confirmed."}, {"id": "a23", "author": "Matt Levine", "date": "2025-10-29", "src_title": "Money Stuff: Put the Data Center in the Box", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-put-the-data-center-in-the-box", "quote": "The modern artificial intelligence boom has created a boom in financial engineering. A lot of people who run big tech companies and AI labs think that they will collectively need to spend trillions of dollars over the next few years building data centers to train and run AI models, buying chips to put in those data centers, buying electricity to run those data centers, and building power plants to provide that electricity.", "claim": "Levine identifies an AI-driven financial engineering boom running parallel to the technology itself, driven by the scale of infrastructure spend required.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Verbatim from pre-paywall intro of bloomberglaw page, date confirmed 2025-10-29. URL 200."}, {"id": "a24", "author": "Matt Levine", "date": "2025-11-11", "src_title": "Money Stuff: AI researcher incentives (via Bainbridge on Corporations)", "url": "https://www.bainbridgeoncorporations.com/p/matt-levine-on-short-term-bias-and", "quote": "It is really an amazing time to be an AI researcher. You can come into work to pursue pure science, uncontaminated by any need for near-term practical applications or making money.", "claim": "Levine observes that AI researchers operate in a capital environment insulated from near-term commercial pressure; venture capital rewards long-term theoretical bets and pays researchers hundreds of millions regardless of revenue.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Verbatim from Bainbridge Substack quoting Money Stuff November 11 2025 (bainbridge records it as Nov 11; bloomberglaw page date confirmed 2025-11-12). URL 200."}, {"id": "a25", "author": "Matt Levine", "date": "2025-11-11", "src_title": "Money Stuff: AI researcher incentives (via Bainbridge on Corporations)", "url": "https://www.bainbridgeoncorporations.com/p/matt-levine-on-short-term-bias-and", "quote": "And when your boss comes to you and says 'hey guy not to be annoying but I am paying you $100 million, is there any way we could turn any of this stuff into money,' you can quit in a huff and find venture capitalists who will give you billions of dollars to be even less commercial.", "claim": "Levine notes that AI researchers who face commercial pressure can simply quit and raise billions from VCs willing to fund even more unbounded research; the capital structure incentivizes ignoring near-term revenue demands.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Verbatim from Bainbridge Substack quoting Money Stuff Nov 11 2025. URL 200."}, {"id": "a26", "author": "Matt Levine", "date": "2025-12-01", "src_title": "Money Stuff: OpenAI Will Own Some Users (Correct)", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-openai-will-own-some-users", "quote": "We have talked before about the business model that Sam Altman proposed for OpenAI in 2019, which was (1) build an artificial superintelligence, (2) ask it how to make money and (3) do that.", "claim": "Levine keeps returning to OpenAI's original business plan, which was explicitly to have no plan until ASI exists, as context for understanding why OpenAI's current financial engineering is an improvisation, not a fraud.", "scope": "finance-markets", "pe_sub": "", "stance": "rejects-conclusion", "note": "Verbatim from pre-paywall intro of bloomberglaw page, date confirmed 2025-12-01. URL 200."}, {"id": "a27", "author": "Matt Levine", "date": "2025-12-01", "src_title": "Money Stuff: OpenAI Will Own Some Users (Correct)", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-openai-will-own-some-users", "quote": "We will create God and then ask it for money.", "claim": "Levine's sardonic summary of OpenAI's 2019 pitch, the company had no revenue model except to build AGI and let it figure out monetization, frames later financial engineering as downstream of that founding absurdity, not evidence of deliberate fraud.", "scope": "finance-markets", "pe_sub": "", "stance": "rejects-conclusion", "note": "Verbatim from pre-paywall intro visible at the bloomberglaw Dec 1 2025 page (also cited in Dec 1 search results). URL 200."}, {"id": "a28", "author": "Matt Levine", "date": "2026-01-05", "src_title": "Money Stuff: Everybody Wants Some AI Debt", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-everybody-wants-some-ai-debt", "quote": "", "claim": "Levine surveys investor appetite for AI-related debt instruments, noting diversity of views: 'many people in finance have views on whether we are raising too much money for data centers, on who is building the best AI models, and on the prospects of particular big AI-related technology companies', with optimism predominant but 'a lot of people complain about a bubble.'", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Paywall article; claim reconstructed from pre-paywall text visible at bloomberglaw URL. The intro phrase 'a lot of people complain about a bubble' is from the visible excerpt. Full text paywalled. URL 200."}, {"id": "a29", "author": "Matt Levine", "date": "2026-02-11", "src_title": "Money Stuff: The AI Whateverpocalypse Trade", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-the-ai-whateverpocalypse-trade", "quote": "Okay so I have a business plan for Sam Altman. Here's what you do. You build an artificial intelligence application for some specific sort of business, coding or tax planning or whatever. You roll it out on a Tuesday morning. You announce it in blandly optimistic terms and do some cool demos. You go on financial television, and when they ask you — as they will — a question like 'won't this disrupt the business model of software-as-a-service companies' or 'won't this put financial advisers out of business,' you smirk ruefully and shake your head and say 'well there …'", "claim": "Levine parodies the AI disruption announcement playbook, release product, vague optimism, TV appearance, as a financial strategy in itself, distinct from whether the product is substantively useful.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Verbatim from pre-paywall intro of bloomberglaw page, date confirmed 2026-02-11. URL 200."}, {"id": "a30", "author": "Matt Levine", "date": "2026-06-03", "src_title": "Money Stuff: Opting Out of the AI Boom", "url": "https://news.bloomberglaw.com/mergers-and-acquisitions/matt-levines-money-stuff-opting-out-of-the-ai-boom", "quote": "In the next few months, SpaceX, Anthropic and OpenAI will all probably go public at massive valuations. They will be fast-tracked into the major stock indexes, because those indexes are designed to reflect the stock market, and reflecting the stock market, in 2027, will absolutely require big allocations to those three companies.", "claim": "Levine predicts that OpenAI, Anthropic, and SpaceX IPOs will force passive index funds to hold massive AI allocations, structurally embedding AI bubble risk into every index investor's portfolio regardless of their views.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Verbatim from pre-paywall intro of bloomberglaw page, date confirmed 2026-06-03. URL 200."}, {"id": "a31", "author": "Matt Levine", "date": "2026-06-08", "src_title": "Money Stuff: No SpaceX in the S&P", "url": "https://news.bloombergtax.com/financial-accounting/matt-levines-money-stuff-no-spacex-in-the-s-p", "quote": "One view of the artificial intelligence boom is that AI will replace all of human economic endeavor. Robots will make the stuff, and robots will manage the factories that make the stuff, and robots will set corporate strategy about what stuff to make, and robots will run the hedge funds that allocate capital to the companies whose robots make the stuff, etc., just robots all the way down. All of the corporate profits that used to go to companies that did stuff — manufacturing, retailing, consulting, whatever — will in the future go to the meta-companies that …", "claim": "Levine articulates the AI maximalist thesis, total automation of economic activity, as one frame investors use to justify massive valuations, while treating this as a framing device rather than his personal verdict.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Verbatim from pre-paywall intro of bloombergtax.com page, date confirmed 2026-06-08. URL 200."}, {"id": "a32", "author": "Matt Bruenig", "date": "2023-04-05", "src_title": "The Solution to AI-Driven Job Displacement Is a Robust Welfare State", "url": "https://jacobin.com/2023/04/artificial-intelligence-chatgpt-job-loss-displacement-labor-reallocation-welfare-state", "quote": "In a typical year, there are around twenty million unemployment events in the United States", "claim": "AI-driven job displacement is not historically exceptional; the US already absorbs ~20 million unemployment events per year, and the structural problem is absent welfare infrastructure, not the technology itself.", "scope": "political-economy", "pe_sub": "welfare-state", "stance": "orthogonal", "note": "Zitron treats AI as a fraud with no real-world impact; Bruenig assumes AI displacement is real and argues the response is welfare policy, not skepticism of the technology."}, {"id": "a33", "author": "Matt Bruenig", "date": "2023-04-05", "src_title": "The Solution to AI-Driven Job Displacement Is a Robust Welfare State", "url": "https://jacobin.com/2023/04/artificial-intelligence-chatgpt-job-loss-displacement-labor-reallocation-welfare-state", "quote": "In societies with very compressed wages and robust universal welfare states — like the Nordic societies — the ultimate differences between different labor market positions are relatively small", "claim": "Nordic-style wage compression and universal welfare states materially reduce the economic harm of AI-driven job displacement by shrinking the gap between labor market positions.", "scope": "political-economy", "pe_sub": "welfare-state", "stance": "orthogonal", "note": "Bruenig's entire framing presupposes AI will displace real jobs, the opposite of Zitron's claim that AI produces nothing of value and displacement fears are hype."}, {"id": "a34", "author": "Matt Bruenig", "date": "2023-04-05", "src_title": "The Solution to AI-Driven Job Displacement Is a Robust Welfare State", "url": "https://jacobin.com/2023/04/artificial-intelligence-chatgpt-job-loss-displacement-labor-reallocation-welfare-state", "quote": "Give unemployed people cash benefits to replace their prior wages. Give them job-search and retraining assistance to help them find new work.", "claim": "The correct policy response to AI displacement is standard welfare-state tools, cash unemployment benefits and retraining, not halting or dismissing the technology.", "scope": "political-economy", "pe_sub": "welfare-state", "stance": "orthogonal", "note": "Bruenig prescribes distributional remedies that assume AI-driven displacement is genuine and ongoing, contradicting Zitron's thesis that the technology is mostly useless."}, {"id": "a35", "author": "Matt Bruenig", "date": "2023-04-05", "src_title": "The Solution to AI-Driven Job Displacement Is a Robust Welfare State", "url": "https://jacobin.com/2023/04/artificial-intelligence-chatgpt-job-loss-displacement-labor-reallocation-welfare-state", "quote": "Wage insurance is the conceptually clear answer to how to cushion the income shock from someone being reallocated into a lower-paying job", "claim": "Wage insurance, compensating workers for the income difference when AI pushes them into lower-paying work, is the targeted policy instrument for AI-driven downward labor mobility.", "scope": "political-economy", "pe_sub": "welfare-state", "stance": "orthogonal", "note": "Designing a program specifically for downward income mobility from AI implies Bruenig takes seriously that AI will lower wages for displaced workers, a direct factual premise Zitron denies."}, {"id": "a36", "author": "Matt Bruenig", "date": "2023-04-05", "src_title": "The Solution to AI-Driven Job Displacement Is a Robust Welfare State", "url": "https://jacobin.com/2023/04/artificial-intelligence-chatgpt-job-loss-displacement-labor-reallocation-welfare-state", "quote": "We need this kind of society at all times, not just during splashy labor reallocation events like the one LLMs might cause.", "claim": "LLM-driven labor reallocation is a real, anticipated event; the welfare-state solution Bruenig advocates is not AI-specific but would handle that disruption among others.", "scope": "political-economy", "pe_sub": "welfare-state", "stance": "orthogonal", "note": "Bruenig accepts LLM displacement as a plausible near-term event, bracketing Zitron's skepticism about AI's productive impact."}, {"id": "a37", "author": "Matt Bruenig", "date": "2023-04-05", "src_title": "The Solution to AI-Driven Job Displacement Is a Robust Welfare State", "url": "https://jacobin.com/2023/04/artificial-intelligence-chatgpt-job-loss-displacement-labor-reallocation-welfare-state", "quote": "An egalitarian society with a robust welfare state creates the kind of stability and minimum living standards that take the financial sting out of things like unemployment, labor reallocation, disability, old age, and having children.", "claim": "A comprehensive egalitarian welfare state is the durable response to AI disruption because it de-risks labor reallocation across all causes, not just technology shocks.", "scope": "political-economy", "pe_sub": "welfare-state", "stance": "orthogonal", "note": "The political-economy prescription is welfare universalism, not AI skepticism. Bruenig simply does not share Zitron's emphasis on debunking AI capability."}, {"id": "a38", "author": "Matt Bruenig", "date": "2026-01-19", "src_title": "Some Thoughts on AI", "url": "https://mattbruenig.com/2026/01/19/some-thoughts-on-ai/", "quote": "For various reasons -- some understandable, others not -- there is a lot of reflexive opposition to AI/LLMs on the left.", "claim": "Bruenig explicitly breaks with left-wing AI skepticism, framing much of it as reflexive and not fully reasoned.", "scope": "political-economy", "pe_sub": "distribution", "stance": "contradicts", "note": "Zitron's AI-skeptic position is precisely the kind of 'reflexive opposition' Bruenig is criticizing here."}, {"id": "a39", "author": "Matt Bruenig", "date": "2026-01-19", "src_title": "Some Thoughts on AI", "url": "https://mattbruenig.com/2026/01/19/some-thoughts-on-ai/", "quote": "What generative AI does and how it does it is genuinely amazing.", "claim": "Bruenig judges the core technical achievement of generative AI to be genuinely impressive, not hype.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Directly contradicts Zitron's thesis that AI is a fraudulent product with no real capability."}, {"id": "a40", "author": "Matt Bruenig", "date": "2026-01-19", "src_title": "Some Thoughts on AI", "url": "https://mattbruenig.com/2026/01/19/some-thoughts-on-ai/", "quote": "I have not written any statistical programming code in many months and I don't see why I would ever write any such code ever again.", "claim": "Bruenig has replaced his own statistical programming work with LLM-generated code, demonstrating concrete personal productivity displacement.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Bruenig uses LLMs to eliminate entire categories of his own labor, the antithesis of Zitron's 'AI does nothing useful' claim."}, {"id": "a41", "author": "Matt Bruenig", "date": "2026-01-19", "src_title": "Some Thoughts on AI", "url": "https://mattbruenig.com/2026/01/19/some-thoughts-on-ai/", "quote": "Those new documents are then summarized by an LLM and posted to the NLRB Edge newsletter, which has 13,000 subscribers.", "claim": "Bruenig runs a live LLM-powered publishing operation with 13,000 subscribers, demonstrating real-world diffusion of AI in labor-law media.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "A functioning, subscriber-supported LLM product contradicts Zitron's claim that AI has no genuine utility or adoption."}, {"id": "a42", "author": "Matt Bruenig", "date": "2026-01-19", "src_title": "Some Thoughts on AI", "url": "https://mattbruenig.com/2026/01/19/some-thoughts-on-ai/", "quote": "I've written extensively about the fact that capitalism distributes the gains from economic production and innovation in a completely insane and indefensible way, but that's a problem with capitalism not with economic production and innovation _per se_.", "claim": "The distributive harms of AI accrue from capitalism's ownership structure, not from the technology, meaning the critique of AI's social effects should target ownership, not capability.", "scope": "political-economy", "pe_sub": "ownership", "stance": "rejects-conclusion", "note": "Bruenig and Zitron both worry about AI's social impact but reach opposite conclusions: Bruenig blames capitalism, Zitron blames the technology being fake/useless."}, {"id": "a43", "author": "Matt Bruenig", "date": "2026-01-19", "src_title": "Some Thoughts on AI", "url": "https://mattbruenig.com/2026/01/19/some-thoughts-on-ai/", "quote": "These concerns also seem quite reasonable to me, but I see them as valid critiques of the capitalist system, not of LLMs. It's a great case for socialism, but not really a case against any particular labor-saving technology.", "claim": "Concerns about AI's social harms are valid but misattributed: they indict capitalism's distribution of technological surplus, not the labor-saving technology itself.", "scope": "political-economy", "pe_sub": "ownership", "stance": "rejects-conclusion", "note": "This is Bruenig's sharpest break with Zitron: he accepts the social critique but routes it through political economy rather than technology debunking."}, {"id": "a44", "author": "Matt Bruenig", "date": "2026-01-19", "src_title": "Some Thoughts on AI", "url": "https://mattbruenig.com/2026/01/19/some-thoughts-on-ai/", "quote": "If something like this actually works, it will prove itself because people will make use of it. Of course, they already are making use of it, but it's early days.", "claim": "Bruenig treats real-world adoption as the empirical test of AI utility, and notes that test is already being passed.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Adoption as proof of utility is the opposite of Zitron's argument that adoption is driven by hype and sunk-cost rather than real value."}, {"id": "a45", "author": "Matt Bruenig", "date": "2026-01-19", "src_title": "Some Thoughts on AI", "url": "https://mattbruenig.com/2026/01/19/some-thoughts-on-ai/", "quote": "The companies that win the scramble for market share will end up minting many billionaires", "claim": "AI's capitalist capture will concentrate wealth at the top, a distributional concern Bruenig frames as an argument for socialism, not against the technology.", "scope": "political-economy", "pe_sub": "market-concentration", "stance": "shares-concern", "note": "Bruenig shares Zitron's worry about AI enriching a narrow elite, but attributes this to capitalism rather than to AI being a fraud."}, {"id": "a46", "author": "Matt Bruenig", "date": "2026-02-10", "src_title": "Technical Details of My LLM-Generated Book", "url": "https://mattbruenig.com/2026/02/10/technical-details-of-my-llm-generated-book/", "quote": "But this particular method of deriving the law from 10,000 carefully selected cases is not something that would have been feasible without LLMs.", "claim": "LLMs enabled a legal research methodology, synthesizing law from 10,000 cases, that was categorically infeasible before their existence.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Bruenig identifies a concrete capability unlock, not incremental improvement but a task that simply could not be done, directly rebutting Zitron's 'nothing new works' thesis."}, {"id": "a47", "author": "Matt Bruenig", "date": "2026-02-10", "src_title": "Technical Details of My LLM-Generated Book", "url": "https://mattbruenig.com/2026/02/10/technical-details-of-my-llm-generated-book/", "quote": "LLMs enable me (1) to do different stuff than I have ever done before because it has abilities I do not, (2) to do more stuff than I have previously been able to do because it works faster", "claim": "LLMs expand what a solo practitioner can produce both qualitatively (new task types) and quantitatively (speed), compounding output beyond any single person's prior capacity.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Bruenig's first-person account of productivity expansion is the empirical counter to Zitron's claim that AI tools do not deliver measurable value in real work."}, {"id": "a48", "author": "Matt Bruenig", "date": "2026-02-10", "src_title": "Technical Details of My LLM-Generated Book", "url": "https://mattbruenig.com/2026/02/10/technical-details-of-my-llm-generated-book/", "quote": "and (3) to in-house things I would have previously had to outsource to a particular person (like an editor) or to a service (like an e-commerce platform).", "claim": "LLMs allow a solo operator to eliminate vendor dependencies (editing, e-commerce), collapsing the cost structure of a publishing operation.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Concrete outsourcing elimination as LLM use-case is direct evidence of utility that contradicts Zitron's skepticism about AI's real-world economic impact."}, {"id": "a49", "author": "Matt Bruenig", "date": "2026-02-12", "src_title": "What even is an autonomous AI agent?", "url": "https://mattbruenig.com/2026/02/12/what-even-is-an-autonomous-ai-agent/", "quote": "LLMs are just like other APIs: you send text to them, they send text back.", "claim": "AI agents are not magic. At their core they are text-in/text-out API calls; their apparent autonomy is a product of surrounding tooling, not intrinsic capability.", "scope": "capability", "pe_sub": "", "stance": "rejects-conclusion", "note": "Bruenig demystifies AI agents without dismissing them: he affirms real utility while stripping mystical framing, a position distinct from both hype and Zitron-style debunking."}, {"id": "a50", "author": "Matt Bruenig", "date": "2026-02-23", "src_title": "My Fully Automated Labor Law Research Tool Is Finally Here", "url": "https://mattbruenig.com/2026/02/23/my-fully-automated-labor-law-research-tool-is-finally-here/", "quote": "you really can just ask any labor law question and get a high-quality answer with citations and links to case law", "claim": "Bruenig's AI labor law tool produces high-quality, cited legal research on demand, a directly commercialized AI product sold to unions and law firms.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "A paid AI product with union clients producing cited legal memos is a direct empirical counter to Zitron's claim that AI output is worthless and unbuyable."}, {"id": "a51", "author": "Matt Bruenig", "date": "2026-02-23", "src_title": "My Fully Automated Labor Law Research Tool Is Finally Here", "url": "https://mattbruenig.com/2026/02/23/my-fully-automated-labor-law-research-tool-is-finally-here/", "quote": "I do intend to sell this for real to firms and unions in a SaaS-type model", "claim": "Bruenig is commercializing AI labor law research for unions, making organized labor a direct customer of his LLM tooling.", "scope": "political-economy", "pe_sub": "labor-unions", "stance": "contradicts", "note": "Unions as paying AI-tool customers refutes Zitron's framing that AI is pure capital-side extraction with no practical utility for workers or their representatives."}, {"id": "a52", "author": "Matt Bruenig", "date": "2026-02-23", "src_title": "My Fully Automated Labor Law Research Tool Is Finally Here", "url": "https://mattbruenig.com/2026/02/23/my-fully-automated-labor-law-research-tool-is-finally-here/", "quote": "It wasn't possible until the most recent models and harnesses", "claim": "Recent LLM capability improvements crossed a threshold that made previously impossible automated legal research feasible; the technology is advancing meaningfully.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Acknowledging a capability step-change in recent models is incompatible with Zitron's stagnation narrative."}, {"id": "a53", "author": "Matt Bruenig", "date": "2026-05-22", "src_title": "I've Got More AI Labor Law Research Tools", "url": "https://www.nlrbedge.com/p/ive-got-more-ai-labor-law-research", "quote": "over 20 unions and law firms are paid monthly subscribers", "claim": "More than 20 unions and law firms are paying monthly for Bruenig's AI legal research tools, demonstrating real commercial traction in the labor movement.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Paying union subscribers to an AI tool is direct evidence of utility and adoption that Zitron's bubble/fraud thesis cannot explain."}, {"id": "a54", "author": "Matt Bruenig", "date": "2026-05-22", "src_title": "I've Got More AI Labor Law Research Tools", "url": "https://www.nlrbedge.com/p/ive-got-more-ai-labor-law-research", "quote": "I use them all of the time in my own practice and clearly quite a few unions and firms that have tried them found them useful enough to pay for.", "claim": "Bruenig validates his AI tools both through personal daily use in his own labor law practice and through the market signal of paying union and firm subscribers.", "scope": "political-economy", "pe_sub": "labor-unions", "stance": "contradicts", "note": "A union-side labor lawyer using and selling AI tools to unions is a politically significant data point against Zitron's framing that AI only serves capital."}, {"id": "a55", "author": "Mariana Mazzucato", "date": "2024-03-03", "src_title": "The Algorithm and Its Discontents", "url": "http://past.jamaica-gleaner.com/article/business/20240303/mazzucato-and-strauss-algorithm-and-its-discontents", "quote": "Now that advances in artificial intelligence already supercharge algorithmic recommendations, making them even more addictive, there is an urgent need for new governance structures oriented towards the 'common good' – rather than a narrowly conceived notion of 'shareholder value'", "claim": "AI is actively supercharging existing algorithmic systems, making them more capable and more addictive, which intensifies the urgency of governance reform oriented toward the common good rather than shareholder value.", "scope": "political-economy", "pe_sub": "market-concentration", "stance": "contradicts", "note": "Co-authored with Ilan Strauss. Published Jamaica Gleaner Mar 3, 2024 (full verbatim text retrieved). The 'AI already supercharges' formulation treats AI's augmented capability as observed fact, directly contradicting Zitron's claim that the technology produces nothing of value."}, {"id": "a56", "author": "Mariana Mazzucato", "date": "2024-03-03", "src_title": "The Algorithm and Its Discontents", "url": "http://past.jamaica-gleaner.com/article/business/20240303/mazzucato-and-strauss-algorithm-and-its-discontents", "quote": "We call these profits 'algorithmic attention rents', because they are generated by passive ownership (like a landlord) rather than from entrepreneurial production to meet consumers' needs.", "claim": "Platform AI profits are better understood as rents, derived from ownership of infrastructure and network effects, rather than from genuine innovation or value creation for users.", "scope": "political-economy", "pe_sub": "distribution", "stance": "shares-concern", "note": "Co-authored with Ilan Strauss. The 'landlord' analogy classifies tech profits as extraction, not creation, overlapping with Zitron's sense that AI companies are grifting, but the mechanism differs: Mazzucato says the tools work but the business model extracts; Zitron says the tools don't work."}, {"id": "a57", "author": "Mariana Mazzucato", "date": "2024-03-03", "src_title": "The Algorithm and Its Discontents", "url": "http://past.jamaica-gleaner.com/article/business/20240303/mazzucato-and-strauss-algorithm-and-its-discontents", "quote": "Creating a digital environment that rewards value creation from innovation, and punishes value extraction from rents (especially in core digital markets), is the fundamental economic challenge of our time.", "claim": "The central task of digital-economy policy is distinguishing and rewarding genuine AI innovation from rent extraction; rents must be taxed or regulated away to restore the link between innovation and reward.", "scope": "political-economy", "pe_sub": "distribution", "stance": "rejects-conclusion", "note": "Co-authored with Ilan Strauss. Frames the problem as a distribution and governance failure, not a technology failure. The call to 'reward value creation from innovation' presupposes such AI-driven innovation exists and needs protection."}, {"id": "a58", "author": "Mariana Mazzucato", "date": "2024-03-03", "src_title": "The Algorithm and Its Discontents", "url": "http://past.jamaica-gleaner.com/article/business/20240303/mazzucato-and-strauss-algorithm-and-its-discontents", "quote": "AI-powered algorithms will influence not just what we consume, but how we produce and create; not just what we choose, but what we think. We must not get this wrong.", "claim": "AI-powered algorithms are becoming cognitive infrastructure shaping production, creativity, and thought, not merely a consumer product, making governance failures at this moment uniquely consequential.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Co-authored with Ilan Strauss. The scope claim. AI shaping how we 'produce and create' and 'what we think', is an empirical assertion of broad, real-world capability. Contradicts Zitron's position that AI is hype with negligible actual impact."}, {"id": "a59", "author": "Mariana Mazzucato", "date": "2024-03-11", "src_title": "Governments Must Shape AI's Future", "url": "https://www.project-syndicate.org/magazine/governments-must-shape-ai-business-not-only-regulate-redistribute-after-the-fact-by-mariana-mazzucato-and-fausto-gernone-2024-03", "quote": "The incentives around AI are aligned for rent extraction, where large companies, acting as intermediaries, amass profits at others' expense.", "claim": "Current AI market structure systematically incentivizes rent extraction by large intermediaries, not genuine value creation, mirroring social media's capture of advertising markets at the expense of content creators, users, and smaller firms.", "scope": "political-economy", "pe_sub": "distribution", "stance": "shares-concern", "note": "Co-authored with Fausto Gernone. PS March 11, 2024 (200). Mazzucato and Zitron share the critique that AI incumbents are capturing disproportionate value, but Mazzucato locates the problem in market structure, not technological non-performance."}, {"id": "a60", "author": "Mariana Mazzucato", "date": "2024-03-11", "src_title": "Governments Must Shape AI's Future", "url": "https://www.project-syndicate.org/magazine/governments-must-shape-ai-business-not-only-regulate-redistribute-after-the-fact-by-mariana-mazzucato-and-fausto-gernone-2024-03", "quote": "While regulation is necessary, it is insufficient. Beyond imposing restrictions on private AI companies, governments must assume an active role in AI development.", "claim": "Reactive AI regulation (restricting harms after the fact) is structurally inadequate; governments must become active co-developers and shapers of AI markets from the outset, as the 'entrepreneurial state' did with the internet, GPS, and touchscreens.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "orthogonal", "note": "Co-authored with Fausto Gernone. The call for an 'active role in AI development' rests on the assumption that there is real AI development happening worth directing, orthogonal to Zitron's fraud thesis."}, {"id": "a61", "author": "Mariana Mazzucato", "date": "2025-02-03", "src_title": "AI for What? Public value creation versus extractive rents", "url": "https://marianamazzucato.substack.com/p/ai-for-what", "quote": "AI is not a sector - it's a general purpose technology that is and will continue to shape all sectors of our economy.", "claim": "AI is a genuine general-purpose technology that will reshape the entire economy, not a narrow product category, making the governance question one of direction, not existence.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Directly contradicts Zitron's thesis that AI is a fraud/bubble with no real utility. Mazzucato treats its transformative potential as established baseline; her critique is about who captures the gains, not whether the technology works."}, {"id": "a62", "author": "Mariana Mazzucato", "date": "2025-02-03", "src_title": "AI for What? Public value creation versus extractive rents", "url": "https://marianamazzucato.substack.com/p/ai-for-what", "quote": "the real question isn't whether or not to regulate AI, but how to actively steer its development toward public value creation rather than value extraction.", "claim": "The governing question for AI is not whether it should exist or be regulated at the margins, but how states can proactively direct its development toward public value rather than private extraction.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "rejects-conclusion", "note": "Zitron argues AI is useless hype; Mazzucato treats the technology's economic significance as settled and redirects debate to distribution and governance of real gains."}, {"id": "a63", "author": "Mariana Mazzucato", "date": "2025-02-03", "src_title": "AI for What? Public value creation versus extractive rents", "url": "https://marianamazzucato.substack.com/p/ai-for-what", "quote": "today's algorithmic systems are increasingly being used to extract what we call 'algorithmic rents' - using AI and machine learning not to create genuine value, but to concentrate market power.", "claim": "The dominant use of AI by large platforms is rent extraction, leveraging market power to capture value already created by others, rather than genuine productive innovation.", "scope": "political-economy", "pe_sub": "market-concentration", "stance": "shares-concern", "note": "Partial overlap with Zitron's critique of AI hype, but the reasoning differs entirely: Mazzucato says the AI works as a rent-extraction mechanism; Zitron says the AI itself does not work."}, {"id": "a64", "author": "Mariana Mazzucato", "date": "2025-02-03", "src_title": "AI for What? Public value creation versus extractive rents", "url": "https://marianamazzucato.substack.com/p/ai-for-what", "quote": "the excessive rents that have been earned by companies that benefitted from these public investments...are now being used to attract top talent from people that used to work in universities and public labs.", "claim": "Tech giants are using rents extracted from publicly funded AI foundations to drain talent from the public institutions that made those foundations possible, undermining future public research capacity.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "rejects-conclusion", "note": "Quote uses '...' ellipsis condensing a single passage. Mazzucato's 'brain drain' argument assumes AI rents are real and substantial enough to competitively poach top researchers, presupposing significant economic value, counter to Zitron's bubble thesis."}, {"id": "a65", "author": "Mariana Mazzucato", "date": "2025-02-07", "src_title": "Resisting Digital Feudalism", "url": "https://www.joserobertoafonso.com.br/resisting-digital-feudalism-mazzucato/", "quote": "Given the pace of AI development, policymakers and civil society must step in now to ensure that the next general-purpose technology serves the public interest. Otherwise, already dominant monopolists will supercharge the socially harmful digital business models they perfected over the past decade.", "claim": "The pace of AI development is real and rapid enough that delayed policy intervention will lock in monopolistic extraction; AI is the 'next general-purpose technology', not a speculative or failed one.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "contradicts", "note": "Published Project Syndicate Feb 7, 2025; live full text at joserobertoafonso.com.br (200). The urgency framing depends entirely on AI being a genuine and fast-moving technology. Directly contradicts Zitron's bubble-and-fraud thesis."}, {"id": "a66", "author": "Mariana Mazzucato", "date": "2025-02-17", "src_title": "Governing AI for the Public Interest", "url": "http://past.jamaica-gleaner.com/article/business/20250216/mazzucato-and-valletti-governing-ai-public-interest", "quote": "The key to governing AI is to treat it not as a sector deserving of more or less support, but rather as a general-purpose technology that can transform all sectors.", "claim": "AI governance must be framed around AI as a general-purpose technology transforming all sectors, not as one industry among many, so the policy question is directional steering, not industrial subsidy.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Co-authored with Tommaso Valletti. Published Jamaica Gleaner Feb 17 2025 (reprint of PS Feb 11 2025). The GPT framing directly contradicts Zitron's characterization of AI as a narrow, overhyped product."}, {"id": "a67", "author": "Mariana Mazzucato", "date": "2025-02-17", "src_title": "Governing AI for the Public Interest", "url": "http://past.jamaica-gleaner.com/article/business/20250216/mazzucato-and-valletti-governing-ai-public-interest", "quote": "the primary bottleneck in AI development is cloud computing power, the market for which is 67 per cent controlled by Amazon, Google, and Microsoft.", "claim": "Three companies control two-thirds of the cloud computing infrastructure that AI depends on, giving them structural monopoly power over who can develop and deploy AI at scale.", "scope": "political-economy", "pe_sub": "market-concentration", "stance": "orthogonal", "note": "Co-authored with Tommaso Valletti. This is an empirical claim about infrastructure concentration, not about AI capability. Orthogonal to Zitron's fraud thesis; it assumes real compute demand exists."}, {"id": "a68", "author": "Mariana Mazzucato", "date": "2025-02-17", "src_title": "Governing AI for the Public Interest", "url": "http://past.jamaica-gleaner.com/article/business/20250216/mazzucato-and-valletti-governing-ai-public-interest", "quote": "AI should be a public good, not a corporate tollbooth.", "claim": "AI infrastructure and outputs should be governed as public goods accessible to all, rather than monopolized by private firms that extract rents from access.", "scope": "political-economy", "pe_sub": "ownership", "stance": "orthogonal", "note": "Co-authored with Tommaso Valletti. Mazzucato's remedy (public ownership/access) runs on the assumption that AI creates real value worth distributing. Orthogonal to Zitron who contests the value creation itself."}, {"id": "a69", "author": "Mariana Mazzucato", "date": "2025-02-17", "src_title": "Governing AI for the Public Interest", "url": "http://past.jamaica-gleaner.com/article/business/20250216/mazzucato-and-valletti-governing-ai-public-interest", "quote": "While AI could deliver profound benefits for all of society, if governments remain passive bystanders, it is likely to do the opposite.", "claim": "AI's beneficial potential is real but not automatic: passive government creates conditions for harm rather than gain, making proactive state intervention a prerequisite for positive outcomes.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "rejects-conclusion", "note": "Co-authored with Tommaso Valletti. The conditional framing ('could deliver profound benefits') presupposes genuine technological capability, incompatible with Zitron's claim of AI as essentially fraudulent."}, {"id": "a70", "author": "Mariana Mazzucato", "date": "2025-07-25", "src_title": "AI Should Help Fund Creative Labor", "url": "https://www.project-syndicate.org/onpoint/how-ai-profits-can-help-fund-cultural-production-by-mariana-mazzucato-and-fausto-gernone-2025-07", "quote": "Generative AI models are built on the collective work of countless people", "claim": "Generative AI systems derive their capability from the aggregate creative and intellectual labor of millions of people (writers, journalists, coders, artists) whose contributions are uncompensated by the companies commercializing that capability.", "scope": "political-economy", "pe_sub": "distribution", "stance": "rejects-conclusion", "note": "Co-authored with Fausto Gernone. PS July 25, 2025 (200). The claim that generative AI is 'built on the collective work of countless people' treats the system as genuinely functional and capable, the opposite of Zitron's position that generative AI produces nothing of real value."}, {"id": "a71", "author": "Carlota Perez", "date": "2005-11-24", "src_title": "Carlota Perez: The Thought Leader Interview (Strategy+Business, Issue 41)", "url": "https://www.strategy-business.com/article/05410", "quote": "I call the first half Installation, because we're installing the new technology in the economy, and the new paradigm in the business and culture.", "claim": "The installation period is the first half of each technological revolution: new technology is being built out, funded primarily by speculative financial capital.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Primary interview with Art Kleiner, Strategy+Business. URL confirmed HTTP 200. One of the clearest definitional statements of the installation/deployment framework."}, {"id": "a72", "author": "Carlota Perez", "date": "2005-11-24", "src_title": "Carlota Perez: The Thought Leader Interview (Strategy+Business, Issue 41)", "url": "https://www.strategy-business.com/article/05410", "quote": "I call it Deployment, because technology is finally deployed to its full benefit, with profits from customers, not speculation, providing the bulk of new investment capital.", "claim": "In the deployment period, financial capital reconnects to production capital; growth is driven by real customer profits rather than speculative returns: this is the golden age.", "scope": "finance-markets", "pe_sub": "", "stance": "contradicts", "note": "Same interview. Establishes the deployment golden age as a distinct, historically recurring phase, the normal outcome after an installation-period crash, not evidence that a technology was fake."}, {"id": "a73", "author": "Carlota Perez", "date": "2005-11-24", "src_title": "Carlota Perez: The Thought Leader Interview (Strategy+Business, Issue 41)", "url": "https://www.strategy-business.com/article/05410", "quote": "That's the price we've historically paid for our ability to reach great booms. The collapse has to be disastrous enough to make it clear to everyone that the time when the stock market drives the growth of the economy is finished.", "claim": "Bubble collapse is the price of admission to a golden age, not evidence of fraud; the crash is structurally necessary to end the frenzy phase and create conditions for productive deployment.", "scope": "finance-markets", "pe_sub": "", "stance": "contradicts", "note": "Verbatim from Strategy+Business interview (HTTP 200). Also cited in antoinebuteau.com (HTTP 200). Directly contradicts Zitron's claim that a future AI crash would vindicate the fraud thesis."}, {"id": "a74", "author": "Carlota Perez", "date": "2005-11-24", "src_title": "Carlota Perez: The Thought Leader Interview (Strategy+Business, Issue 41)", "url": "https://www.strategy-business.com/article/05410", "quote": "Installation culminates in a time of 'frenzy' (in our own time, the high-tech bubble of the roaring 1990s).", "claim": "The frenzy sub-phase, characterized by speculative excess, decoupling of financial from production capital, widening inequality, and asset inflation, is the predictable culmination of the installation period.", "scope": "finance-markets", "pe_sub": "", "stance": "rejects-conclusion", "note": "Verbatim from Strategy+Business 2005 interview (HTTP 200). Framing the AI boom as 'frenzy' is Perez's framework for real revolutions, not for frauds."}, {"id": "a75", "author": "Carlota Perez", "date": "2017-08-28", "src_title": "Are We on the Verge of a New Golden Age? (Strategy+Business)", "url": "https://www.strategy-business.com/article/Are-We-on-the-Verge-of-a-New-Golden-Age", "quote": "the information and communications technology (ICT) revolution is far from complete", "claim": "The ICT revolution, within which AI is a development, has not yet reached its deployment phase; much of the economy has not yet been transformed by it, so the technological potential is real and substantial.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Verbatim from Strategy+Business 2017 interview (HTTP 200). Directly challenges any claim that ICT/AI transformation is hype. Perez argues the deployment hasn't even happened yet."}, {"id": "a76", "author": "Carlota Perez", "date": "2017-08-28", "src_title": "Are We on the Verge of a New Golden Age? (Strategy+Business)", "url": "https://www.strategy-business.com/article/Are-We-on-the-Verge-of-a-New-Golden-Age", "quote": "the public sector has to lead the way back after the major bubble collapses", "claim": "Post-crash recovery and transition to the deployment golden age historically requires active state leadership: directing investment, setting regulatory frameworks, and ensuring finance recouples to production.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "orthogonal", "note": "Verbatim from Strategy+Business 2017 interview (HTTP 200). Perez's state-direction thesis: market alone cannot navigate the turning point."}, {"id": "a77", "author": "Carlota Perez", "date": "2019-03-31", "src_title": "Twitter / X (@carlotaprzperez)", "url": "https://stratechery.com/2021/the-death-and-birth-of-technological-revolutions/", "quote": "I see the present as the 1930s, the turning point of the IT surge. We have had 2 frenzies and we have not yet had a golden age.", "claim": "As of 2019, Perez located the ICT revolution at its 'turning point', analogous to the 1930s inter-war period, having passed through two frenzy bubbles (1990s dot-com, 2008 credit) without yet reaching the deployment golden age.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Verbatim tweet by Perez (March 31, 2019), reproduced in Stratechery (HTTP 200) which fetched the tweet directly. The turning-point framing predates the AI boom but provides the framework for placing it."}, {"id": "a78", "author": "Carlota Perez", "date": "2021-01-01", "src_title": "The Death and Birth of Technological Revolutions (Stratechery, quoting FT Tech Tonic podcast)", "url": "https://stratechery.com/2021/the-death-and-birth-of-technological-revolutions/", "quote": "The important thing is that the previous revolutions had the Golden Age after the recession that follows the crash.", "claim": "Every prior major technological revolution produced a golden age of broad economic prosperity, but only after the post-bubble recession; the crash and recession are the historically necessary mechanism, not a terminus.", "scope": "finance-markets", "pe_sub": "", "stance": "contradicts", "note": "Verbatim from FT Tech Tonic podcast (Perez speaking), reproduced in Stratechery (HTTP 200). Core rebuttal to the argument that an AI bust would prove the technology was worthless."}, {"id": "a79", "author": "Carlota Perez", "date": "2021-01-01", "src_title": "The Death and Birth of Technological Revolutions (Stratechery, quoting FT Tech Tonic podcast)", "url": "https://stratechery.com/2021/the-death-and-birth-of-technological-revolutions/", "quote": "every Golden Age has had to do with social-political choices made by governments, because capitalism really only becomes legitimate when the greed of some is for the benefit of the many.", "claim": "The deployment golden age is not automatic after a crash: it requires deliberate state action to tilt the playing field so that productive deployment is profitable; laissez-faire after the crash produces a 'gilded age' not a golden age.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "orthogonal", "note": "Verbatim from FT Tech Tonic podcast, reproduced in Stratechery (HTTP 200). Perez's political-economy argument: state must shape post-crash deployment, especially for green/sustainable direction."}, {"id": "a80", "author": "Carlota Perez", "date": "2022-06-14", "src_title": "A Long Delayed Golden Age: Why Has the ICT Installation Period Lasted So Long? (IIPP/Medium)", "url": "https://medium.com/iipp-blog/a-long-delayed-golden-age-or-why-has-the-ict-installation-period-lasted-so-long-b3471a0aaaeb", "quote": "the process of diffusion of each successive technological revolution has taken between forty and sixty years", "claim": "Each of the five major technological revolutions takes 40-60 years to fully diffuse through the economy; the ICT revolution that began in 1971 is still inside its historical diffusion window.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Verbatim from Perez's own IIPP/Medium essay. WebFetch confirmed live content; curl returns 403 (Cloudflare bot-block). Listed on carlotaperez.org/articles-and-blogs/ (HTTP 200)."}, {"id": "a81", "author": "Carlota Perez", "date": "2022-06-14", "src_title": "A Long Delayed Golden Age: Why Has the ICT Installation Period Lasted So Long? (IIPP/Medium)", "url": "https://medium.com/iipp-blog/a-long-delayed-golden-age-or-why-has-the-ict-installation-period-lasted-so-long-b3471a0aaaeb", "quote": "the most acute impediment to a golden age deployment is the continued decoupling of finance from production", "claim": "Finance remaining in casino mode after the NASDAQ crash, rather than recoupling to production, is the structural reason the ICT golden age has been delayed, not any deficiency of the underlying technology.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Verbatim from Perez's IIPP/Medium essay. WebFetch confirmed live. Perez attributes delayed golden age to financial-institutional failure, not technology failure, orthogonal to Zitron's fraud claim."}, {"id": "a82", "author": "Carlota Perez", "date": "2022-06-14", "src_title": "A Long Delayed Golden Age: Why Has the ICT Installation Period Lasted So Long? (IIPP/Medium)", "url": "https://medium.com/iipp-blog/a-long-delayed-golden-age-or-why-has-the-ict-installation-period-lasted-so-long-b3471a0aaaeb", "quote": "The usual casino of the frenzy periods has remained in force since the NASDAQ bubble", "claim": "The ICT revolution has been stuck in extended frenzy/casino mode since the NASDAQ crash; post-bubble institutions failed to pivot finance toward productive deployment as prior revolutions eventually did.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Verbatim from Perez's IIPP/Medium essay. WebFetch confirmed live. This is Perez's own 'shares concern' moment: she worries about financialization persisting, but her diagnosis is structural, not fraud."}, {"id": "a83", "author": "Carlota Perez", "date": "2024-03-11", "src_title": "What Is AI's Place in History? (Project Syndicate)", "url": "https://www.project-syndicate.org/magazine/ai-is-part-of-larger-technological-revolution-by-carlota-perez-1-2024-03", "quote": "Artificial intelligence is almost certainly revolutionary in the sense that it will spawn new technology platforms, transform or eliminate many industries, and create new ones.", "claim": "Perez affirms AI is genuinely, substantively revolutionary, not a hype cycle or fraud, based on historical pattern-matching across five prior technological revolutions.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Perez's most recent public statement on AI. Article is paywalled but lede is publicly visible and confirmed live (HTTP 200). Directly contradicts Zitron's fraud thesis."}, {"id": "a84", "author": "Carlota Perez", "date": "2024-03-11", "src_title": "What Is AI's Place in History? (Project Syndicate)", "url": "https://www.project-syndicate.org/magazine/ai-is-part-of-larger-technological-revolution-by-carlota-perez-1-2024-03", "quote": "Everyone is talking about artificial intelligence as though it represents the next technological revolution. In fact, it is better understood as a key development within the still-evolving information-communications-technology (ICT) revolution, which started in the 1970s with the microprocessor.", "claim": "AI is not a standalone new revolution but a major development within the ICT revolution begun in the 1970s; the ICT revolution is still unfolding and has not yet reached its deployment golden age.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Verbatim from the publicly visible lede of the paywalled Project Syndicate article. HTTP 200 confirmed. Also quoted in workforcefuturist.substack.com (HTTP 103/200)."}, {"id": "a85", "author": "J. Bradford DeLong", "date": "2024-12-31", "src_title": "MAMLMs: Scaling Laws, Two Roads, and Financial Winter?", "url": "https://substack.com/@delongonsubstack/note/c-83797321", "quote": "Feeding the internet to a GPT LLM produced an extremely persuasive and linguistically fluent internet s***poster. And there, I think, the simple 'scaling law' story ends. Now do not get me wrong—that is an amazing accomplishment. But it is not the road to A(G)I, true AI, or SuperIntelligence.", "claim": "Scaling laws for LLMs have delivered impressive but narrow capability; the path to AGI/superintelligence is not simply more of the same training.", "scope": "capability", "pe_sub": "", "stance": "orthogonal", "note": "Skeptical of AGI timeline hype but not of real capability; this is a nuance, not a fraud claim."}, {"id": "a86", "author": "J. Bradford DeLong", "date": "2025-06-24", "src_title": "MAMLM as a General Purpose Technology: The Ghost in the GDP Machine", "url": "https://braddelong.substack.com/p/mamlm-as-a-general-purpose-technology", "quote": "General-purpose technologies are those rare innovations—think James Watt's steam engine in the late 18th century, Edison's electrification in the 19th, or Turing's computer in the 20th—that fundamentally alter the production possibilities of entire economies.", "claim": "DeLong explicitly classifies AI/MAMLM alongside the steam engine, electrification, and computers as a genuine general-purpose technology (GPT) with economy-wide transformative potential.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Directly contradicts Zitron's fraud/useless framing; DeLong places AI in the pantheon of historically transformative technologies."}, {"id": "a87", "author": "J. Bradford DeLong", "date": "2025-06-24", "src_title": "MAMLM as a General Purpose Technology: The Ghost in the GDP Machine", "url": "https://braddelong.substack.com/p/mamlm-as-a-general-purpose-technology", "quote": "installing the dynamo is easy; reorganizing the factory to exploit it is hard. The same holds for AI.", "claim": "The constraint on AI's impact is organizational, not technological: firms must redesign workflows to capture productivity gains, just as electrification required factory redesign.", "scope": "diffusion-utility", "pe_sub": "", "stance": "orthogonal", "note": "Explains slow measured productivity impact without endorsing bubble thesis; diffusion lag is historical norm for GPTs."}, {"id": "a88", "author": "J. Bradford DeLong", "date": "2025-06-24", "src_title": "MAMLM as a General Purpose Technology: The Ghost in the GDP Machine", "url": "https://braddelong.substack.com/p/mamlm-as-a-general-purpose-technology", "quote": "the impact of current-generation AI on U.S. GDP growth is likely to be 'nontrivial, but modest'—perhaps a 1% cumulative boost over a decade", "claim": "DeLong projects a real but modest near-term GDP boost from AI, approximately 1% cumulative over ten years, rejecting both the bubble thesis and the hyperbolic bull case.", "scope": "diffusion-utility", "pe_sub": "", "stance": "rejects-conclusion", "note": "AI delivers real economic value; framing it as 'useless' is wrong. Modest ≠ zero."}, {"id": "a89", "author": "J. Bradford DeLong", "date": "2025-06-24", "src_title": "MAMLM as a General Purpose Technology: The Ghost in the GDP Machine", "url": "https://braddelong.substack.com/p/mamlm-as-a-general-purpose-technology", "quote": "perhaps 5% of all tasks in the U.S. economy are currently profitable to automate with existing AI systems", "claim": "Only a small fraction of economic tasks are currently profitable to automate with AI, reflecting real but limited near-term reach, not fraud.", "scope": "diffusion-utility", "pe_sub": "", "stance": "orthogonal", "note": "Concedes limited current deployment scope; consistent with slow diffusion pattern for GPTs."}, {"id": "a90", "author": "J. Bradford DeLong", "date": "2025-06-24", "src_title": "MAMLM as a General Purpose Technology: The Ghost in the GDP Machine", "url": "https://braddelong.substack.com/p/mamlm-as-a-general-purpose-technology", "quote": "The flood of cultural and intellectual production means that with even a slightly effective filter the quality of the experiences you obtain goes way up.", "claim": "AI delivers enormous consumer surplus through improved content quality and filtering, welfare gains that don't appear in GDP but are economically real.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Real user welfare gains are central to DeLong's case that AI is not useless."}, {"id": "a91", "author": "J. Bradford DeLong", "date": "2025-06-24", "src_title": "MAMLM as a General Purpose Technology: The Ghost in the GDP Machine", "url": "https://braddelong.substack.com/p/mamlm-as-a-general-purpose-technology", "quote": "This productivity decline is not real—a better, human welfare-based measure would include the value to the user of interacting with Amazon via the natural-language interface. But it will be reported.", "claim": "GDP statistics will initially understate AI's true economic impact because consumer surplus from AI interfaces is not captured in national accounts.", "scope": "diffusion-utility", "pe_sub": "", "stance": "contradicts", "note": "Standard productivity statistics systematically miss the welfare gains DeLong considers most important."}, {"id": "a92", "author": "J. Bradford DeLong", "date": "2025-06-30", "src_title": "The ROI Problem of AI: Dazzling Capabilities, But Powerful Market Incentives Blocking Bottom-Line Corporate-Profit Gains", "url": "https://braddelong.substack.com/p/the-roi-problem-of-ai-dazzling-capabilities", "quote": "'Artificial intelligence' seems to be coming everywhere, but its profits are not.", "claim": "AI is genuinely diffusing into the economy, but the technology's value flows primarily to users rather than to shareholders or producers.", "scope": "finance-markets", "pe_sub": "", "stance": "shares-concern", "note": "Aligns with Zitron's concern about investor returns, but for the opposite reason: competition, not fraud."}, {"id": "a93", "author": "J. Bradford DeLong", "date": "2025-06-30", "src_title": "The ROI Problem of AI: Dazzling Capabilities, But Powerful Market Incentives Blocking Bottom-Line Corporate-Profit Gains", "url": "https://braddelong.substack.com/p/the-roi-problem-of-ai-dazzling-capabilities", "quote": "If your competitors are building-out MAMLM capabilities and charging for it, you have a business model if you can outperform them. If your competitors are building-out MAMLM capabilities and not charging for it, you don't.", "claim": "Competitive dynamics force AI providers to offer capabilities for free or near-free, destroying potential profits even as the technology delivers real value to users.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "AI is real and valuable; the profit problem is structural competition, not lack of utility."}, {"id": "a94", "author": "J. Bradford DeLong", "date": "2025-06-30", "src_title": "The ROI Problem of AI: Dazzling Capabilities, But Powerful Market Incentives Blocking Bottom-Line Corporate-Profit Gains", "url": "https://braddelong.substack.com/p/the-roi-problem-of-ai-dazzling-capabilities", "quote": "Think railroads in the 1800s. One railroad from place-to-place creates a fortune. Two railroads eke out a living. Three railroads bankrupt everyone…", "claim": "AI economics replicate the historical railroad pattern: genuine transformative technology whose competitive proliferation destroys investor returns while delivering societal value.", "scope": "finance-markets", "pe_sub": "", "stance": "orthogonal", "note": "Railroads were not frauds; they remade civilization. Same logic applies to DeLong's AI argument."}, {"id": "a95", "author": "J. Bradford DeLong", "date": "2025-07-24", "src_title": "Behind the Hype: What 'AI' Is & Isn't", "url": "https://www.milkenreview.org/articles/behind-the-hype?IssueID=58", "quote": "AI technology is the Next Big Thing, likely to disrupt business (and society) in ways predictable and not. It is also, on balance, almost surely a Good Thing, offering the prospect of rapid productivity change and a path toward dramatic improvements in services ranging from medicine to education.", "claim": "DeLong's bottom-line verdict: AI is a genuine, beneficial transformative technology, though with serious risks for investors.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "Explicit bottom-line endorsement of AI as real and good, directly contradicting the fraud/useless framing."}, {"id": "a96", "author": "J. Bradford DeLong", "date": "2025-07-24", "src_title": "Behind the Hype: What 'AI' Is & Isn't", "url": "https://www.milkenreview.org/articles/behind-the-hype?IssueID=58", "quote": "This rapid, radical shift in platform dynamics is not only the consequence of powerful new technologies that humans could benefit from. It is driving a multitrillion-dollar transfer of wealth from platform-service suppliers to platform users.", "claim": "AI is generating multi-trillion dollar consumer surplus, a wealth transfer from producers to users at historic scale.", "scope": "finance-markets", "pe_sub": "distribution", "stance": "contradicts", "note": "AI delivers enormous real economic value; it transfers to users rather than shareholders."}, {"id": "a97", "author": "J. Bradford DeLong", "date": "2025-07-24", "src_title": "Behind the Hype: What 'AI' Is & Isn't", "url": "https://www.milkenreview.org/articles/behind-the-hype?IssueID=58", "quote": "Natural-language interfaces are, in themselves, general-purpose technologies that promise a material boost to human productivity in accomplishing white-collar work.", "claim": "The natural-language interface layer of AI is itself a genuine general-purpose technology with broad productivity implications, independent of underlying model capabilities.", "scope": "capability", "pe_sub": "", "stance": "contradicts", "note": "DeLong identifies the interface layer as the key GPT innovation, not AGI."}, {"id": "a98", "author": "J. Bradford DeLong", "date": "2025-08-09", "src_title": "Digital Perikles vs. the Odd Roommate: State of the AI on ChatGPT5 Day", "url": "https://braddelong.substack.com/p/digital-perikles-vs-the-odd-roommate", "quote": "These things are merely (merely!) lossy summarization-engine info-cultural technologies, while true, does not help us figure out how we can use them given that they are unreasonably effective", "claim": "AI systems are 'lossy summarization engines', a technically reductive description, yet DeLong insists they remain 'unreasonably effective' and practically valuable.", "scope": "capability", "pe_sub": "", "stance": "orthogonal", "note": "DeLong's technical skepticism about what AI 'really is' coexists with acknowledgment of genuine utility."}, {"id": "a99", "author": "Daron Acemoglu", "date": "2023-05-17", "src_title": "An AI challenge only humans can solve", "url": "https://news.mit.edu/2023/power-and-progress-book-ai-inequality-0517", "quote": "The current path of AI is neither good for the economy nor for democracy, and these two problems, unfortunately, reinforce each other.", "claim": "AI's economic and political harms are mutually reinforcing: economic inequality weakens democratic checks, which in turn allow more inequality-deepening AI deployment.", "scope": "political-economy", "pe_sub": "distribution", "stance": "shares-concern", "note": "Co-stated with Simon Johnson at Power and Progress launch; key thesis of the book."}, {"id": "a100", "author": "Daron Acemoglu", "date": "2024-05-01", "src_title": "The Simple Macroeconomics of AI (NBER Working Paper 32487)", "url": "https://economics.mit.edu/sites/default/files/2024-04/The%20Simple%20Macroeconomics%20of%20AI.pdf", "quote": "", "claim": "Acemoglu's model estimates AI will contribute no more than 0.53 to 0.66% increase in total factor productivity over the next decade, translating to roughly 0.064% annual TFP growth, well below optimistic forecasts from Goldman Sachs and McKinsey.", "scope": "diffusion-utility", "pe_sub": "productivity-growth", "stance": "shares-concern", "note": "PDF binary; quote left blank per hard rules. Statistics corroborated by multiple secondary sources (AEI, MIT Economics news, Intelligence Strategy Substack) citing the NBER paper directly."}, {"id": "a101", "author": "Daron Acemoglu", "date": "2024-05-01", "src_title": "The Simple Macroeconomics of AI (NBER Working Paper 32487)", "url": "https://economics.mit.edu/sites/default/files/2024-04/The%20Simple%20Macroeconomics%20of%20AI.pdf", "quote": "", "claim": "Acemoglu finds only 20% of U.S. labor tasks are exposed to AI, and of those, only 23% can be profitably automated within the next decade, yielding average labor cost savings of about 27% per automated task.", "scope": "diffusion-utility", "pe_sub": "productivity-growth", "stance": "shares-concern", "note": "PDF binary; statistics corroborated by AEI (June 2024) and Intelligence Strategy Substack (Feb 2025) citing the NBER paper. Calls Goldman/McKinsey forecasts 'hyperbolic'."}, {"id": "a102", "author": "Daron Acemoglu", "date": "2024-09-03", "src_title": "Daron Acemoglu on Artificial Intelligence", "url": "https://www.socialsciencespace.com/2024/09/daron-acemoglu-on-artificial-intelligence/", "quote": "Automation is not our enemy. Excessive automation is our enemy.", "claim": "Acemoglu explicitly defends automation in principle: his concern is degree and direction, not automation per se.", "scope": "political-economy", "pe_sub": "labor-unions", "stance": "orthogonal", "note": "Important nuance: Acemoglu is not anti-AI or anti-automation categorically."}, {"id": "a103", "author": "Daron Acemoglu", "date": "2024-09-03", "src_title": "Daron Acemoglu on Artificial Intelligence", "url": "https://www.socialsciencespace.com/2024/09/daron-acemoglu-on-artificial-intelligence/", "quote": "I feel AI is going in the wrong direction and taking us down with it.", "claim": "Acemoglu's concern about AI is directional and institutional: the technology's current trajectory is harmful, but the technology itself is real and could be redirected.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "shares-concern", "note": "Shares concern about AI's current course; does not deny its capability or existence."}, {"id": "a104", "author": "Daron Acemoglu", "date": "2024-10-14", "src_title": "Nobel Laureate Acemoglu on Automation, Inequality, and the Future of Society", "url": "https://www.resetdoc.org/story/nobel-laureate-acemoglu-automation-inequality-future-society/", "quote": "AI adoption has so far been driven by the same business model that aims to substitute algorithms for humans.", "claim": "Current AI deployment follows a business model of replacement rather than augmentation, compounding pre-existing labor market inequality.", "scope": "political-economy", "pe_sub": "labor-unions", "stance": "shares-concern", "note": "Empirical claim about current deployment pattern, not a claim that AI is technologically fake."}, {"id": "a105", "author": "Daron Acemoglu", "date": "2024-10-14", "src_title": "Nobel Laureate Acemoglu on Automation, Inequality, and the Future of Society", "url": "https://www.resetdoc.org/story/nobel-laureate-acemoglu-automation-inequality-future-society/", "quote": "The question that will be critical is who will control technology? Who will control AI?", "claim": "AI's impact depends fundamentally on governance and power: who shapes the technology determines whether it serves workers or capital.", "scope": "political-economy", "pe_sub": "ownership", "stance": "orthogonal", "note": "Acemoglu's frame is political economy of control, not fraud detection."}, {"id": "a106", "author": "Daron Acemoglu", "date": "2024-12-06", "src_title": "What do we know about the economics of AI?", "url": "https://economics.mit.edu/news/daron-acemoglu-what-do-we-know-about-economics-ai", "quote": "My argument is that we currently have the wrong direction for AI.", "claim": "Acemoglu's central critique is not that AI is useless, but that it is being steered toward automation rather than worker augmentation, making the technology socially harmful.", "scope": "political-economy", "pe_sub": "public-investment-direction", "stance": "shares-concern", "note": "Shares the concern about AI's current trajectory, but the diagnosis differs from Zitron: the problem is direction, not existence."}, {"id": "a107", "author": "Daron Acemoglu", "date": "2024-12-06", "src_title": "What do we know about the economics of AI?", "url": "https://economics.mit.edu/news/daron-acemoglu-what-do-we-know-about-economics-ai", "quote": "We're using it too much for automation and not enough for providing expertise and information to workers.", "claim": "Current AI deployment over-indexes on replacing workers rather than enhancing their capabilities, which is a policy and design choice, not a technological inevitability.", "scope": "political-economy", "pe_sub": "labor-unions", "stance": "shares-concern", "note": "Acemoglu's critique is directional, not existential; AI could be genuinely valuable if redirected toward augmentation."}, {"id": "a108", "author": "Daron Acemoglu", "date": "2024-12-06", "src_title": "What do we know about the economics of AI?", "url": "https://economics.mit.edu/news/daron-acemoglu-what-do-we-know-about-economics-ai", "quote": "I don't think we should belittle 0.5 percent in 10 years. That's better than zero. But it's just disappointing relative to the promises that people in the industry and in tech journalism are making.", "claim": "Acemoglu acknowledges AI will deliver real (if modest) productivity gains, explicitly not zero, but the hype far exceeds what the evidence supports.", "scope": "diffusion-utility", "pe_sub": "", "stance": "shares-concern", "note": "Critically: Acemoglu says AI is 'better than zero,' directly contradicting Zitron's 'useless/fraud' framing. His complaint is about overstatement, not nonexistence."}, {"id": "a109", "author": "Daron Acemoglu", "date": "2026-02-24", "src_title": "AI Is Not Improving Productivity", "url": "https://sloanreview.mit.edu/audio/ai-is-not-improving-productivity-nobel-laureate-daron-acemoglu/", "quote": "we're having slower productivity improvements today than we did in the '50s, '60s, '70s, those boring pre-digital days", "claim": "Despite AI hype, measured aggregate productivity growth is slower now than in the pre-digital era, suggesting AI has not yet delivered macroeconomic gains.", "scope": "diffusion-utility", "pe_sub": "productivity-growth", "stance": "shares-concern", "note": "Consistent with Zitron's skepticism about productivity impact, but Acemoglu's diagnosis is structural/directional, not fraud."}, {"id": "a110", "author": "Daron Acemoglu", "date": "2026-04-26", "src_title": "AI is bad for equality, the working class, and democracy", "url": "https://www.calcalistech.com/ctechnews/article/so5mrkqny", "quote": "Under the banner of AGI (Artificial General Intelligence), systems for widespread automation are being developed that will reduce employment in the long term. It will not cause mass unemployment in the near future, but this model will increase inequality and reduce the number of meaningful jobs. My conclusion is that this development is bad for equality, bad for the working class, bad for democracy, and bad for social cohesion.", "claim": "The AGI framing legitimizes a broad automation push that Acemoglu believes will depress employment, increase inequality, and damage democratic institutions.", "scope": "political-economy", "pe_sub": "distribution", "stance": "shares-concern", "note": "One of Acemoglu's most sweeping statements; concern is about the AGI/automation agenda, not AI capability denial."}];